// Tourism investment worlds: fictional USD, separate from the HUB entry requirement.
export const ESTATE_WORLDS={2:{id:2,size:5,cells:25,minPlayers:3,maxPlayers:6,minHub:1001,months:36,scale:1,cash:220000,reserve:30000,debt:120000,salary:12000,living:6500,payment:2500},3:{id:3,size:6,cells:36,minPlayers:4,maxPlayers:6,minHub:10000,months:48,scale:5,cash:1100000,reserve:150000,debt:600000,salary:60000,living:32500,payment:12500}};
const projects=[
 ['resort','🏝',['Khu nghỉ dưỡng','Resort'],90000,220000,17000,6500],['hotel','🏨',['Khách sạn','Hotel'],70000,160000,13000,5000],['homestay','🏡',['Homestay','Homestay'],28000,48000,4300,1500],['farmstay','🌿',['Farmstay','Farmstay'],35000,60000,5100,1900],['dorm','🛏',['Khu lưu trú dorm','Dormitory'],18000,30000,2900,1000],['restaurant','🍽',['Quán ăn','Restaurant'],25000,45000,5300,2600],['cafe','☕',['Quán cà phê','Café'],22000,35000,3700,1700],['convenience','🛒',['Cửa hàng tiện lợi','Convenience store'],30000,50000,5600,2800],['supermarket','🏬',['Siêu thị','Supermarket'],65000,130000,12000,6500],['salon','✂',['Salon tóc','Hair salon'],18000,28000,3100,1400],['spa','🪷',['Spa','Spa'],32000,65000,5800,2400],['bakery','🥐',['Tiệm bánh','Bakery'],20000,35000,3900,1900],['bike','🚲',['Trạm thuê xe','Bike rentals'],16000,24000,2700,900],['seafood','🐟',['Nhà hàng hải sản','Seafood restaurant'],38000,70000,7200,3400],['market','🎁',['Cửa hàng đặc sản','Local gifts'],24000,32000,3700,1700],['eco','🌳',['Khu cắm trại','Campsite'],28000,40000,3600,1200]];
export function estateMap(world){const w=ESTATE_WORLDS[world];if(!w)throw Error('INVALID_WORLD');let landIndex=0;return Array.from({length:w.cells},(_,i)=>{if(i===0)return {index:i,kind:'start',icon:'⚑',name:['Cổng khu du lịch','Tourism gateway']};if(i%9===0)return {index:i,kind:'market',icon:'↗',name:['Mùa du lịch','Tourism season']};if(i%7===0)return {index:i,kind:'surprise',icon:'◇',name:['Biến cố kinh doanh','Business event']};const [kind,icon,name,land,build,revenue,operating]=projects[landIndex%projects.length],district=1+Math.floor(landIndex++/projects.length),factor=w.scale*(district===1?1:1.2);return {index:i,kind:'land',project:kind,icon,name:name.map(n=>n+(district>1?' · '+district:'')),land:Math.round(land*factor),build:Math.round(build*factor),revenue:Math.round(revenue*factor),operating:Math.round(operating*factor),minimum:Math.round((land+build*.6)*factor)};});}
const cash=n=>Math.round(n);const hash=(seed,n)=>{let x=(seed+n*1013904223)>>>0;x^=x>>>16;x=Math.imul(x,0x7feb352d);return(x^(x>>>15))>>>0;};
export function newEstateRoom(world,members,seed,now=Date.now()){const w=ESTATE_WORLDS[world];if(!w||members.length<w.minPlayers||members.length>w.maxPlayers)throw Error('PLAYER_COUNT');return {version:1,world,seed:seed>>>0,active:true,done:false,turn:0,round:1,deadline:now+60000,rolled:false,pending:null,properties:{},season:1,log:[],players:members.map(m=>({id:m.id,name:m.name,cash:w.cash,reserve:w.reserve,debt:w.debt,position:0,month:0,shortfall:0,finished:false,surrendered:false,last:null}))};}
export const estateAssets=(d,seat)=>{const map=estateMap(d.world);return Object.entries(d.properties).filter(([,p])=>p.owner===seat).map(([id,p])=>({...map[Number(id)],...p}));};
export const estateWorth=(d,seat)=>{const p=d.players[seat];return cash(p.cash+p.reserve-p.debt+estateAssets(d,seat).reduce((n,a)=>n+a.land+(a.stage>=2?a.build*.6:0)+(a.stage>=3?a.build*.4:0),0));};
function pay(p,amount){const fromCash=Math.min(p.cash,amount);p.cash-=fromCash;const fromReserve=Math.min(p.reserve,amount-fromCash);p.reserve-=fromReserve;const unpaid=cash(amount-fromCash-fromReserve);p.shortfall+=unpaid;return unpaid;}
function record(d,p,text){d.log.unshift({seat:d.turn,month:p.month,text});d.log=d.log.slice(0,80);}
function next(d,now){const w=ESTATE_WORLDS[d.world],p=d.players[d.turn];if(p.month>=w.months||p.shortfall>0||p.surrendered)p.finished=true;d.pending=null;d.rolled=false;if(d.players.every(x=>x.finished)){d.active=false;d.done=true;delete d.deadline;return;}for(let k=1;k<=d.players.length;k++){const i=(d.turn+k)%d.players.length;if(!d.players[i].finished){d.turn=i;d.deadline=now+60000;d.round=1+Math.min(...d.players.filter(x=>!x.finished).map(x=>x.month));return;}}}
function monthly(d,p){const w=ESTATE_WORLDS[d.world];p.month++;const items=estateAssets(d,d.turn).filter(a=>a.stage===3).map(a=>{const demand=.75+(hash(d.seed,p.month*71+a.index)%51)/100,revenue=cash(a.revenue*d.season*demand);return {index:a.index,revenue,operating:a.operating,net:revenue-a.operating};}),revenue=items.reduce((n,a)=>n+a.revenue,0),operating=items.reduce((n,a)=>n+a.operating,0),principal=Math.min(p.debt,w.payment);p.cash+=w.salary+revenue;const livingUnpaid=pay(p,w.living),debtUnpaid=pay(p,principal),operatingUnpaid=pay(p,operating),unpaid=livingUnpaid+debtUnpaid+operatingUnpaid;p.debt=Math.max(0,p.debt-(principal-debtUnpaid));p.last={salary:w.salary,revenue,operating,living:w.living,principal,unpaid,items};}
export function estateOffer(d,seat=d.turn){const p=d.players[seat],tile=estateMap(d.world)[p.position],owned=d.properties[p.position];if(tile.kind!=='land')return null;const eligible=!owned||owned.owner===seat;if(!eligible)return {tile,owned,action:'visit',cost:owned.stage===3?Math.max(500,cash(tile.revenue*.12)):0};const stage=owned?.stage||0,action=['land','build','open','complete'][stage],cost=stage===0?tile.land:stage===1?cash(tile.build*.6):stage===2?cash(tile.build*.4):0;return {tile,owned,action,cost,affordable:p.cash>=(stage===0?tile.minimum:cost)};}
export function estateAct(d,seat,action,now=Date.now()){if(!d?.active||seat!==d.turn)return false;const p=d.players[seat],w=ESTATE_WORLDS[d.world];
 if(action==='surrender'){p.surrendered=true;record(d,p,['Bỏ chặng đầu tư','Investment stage abandoned']);next(d,now);return true;}
 if(action==='roll'){if(d.rolled)return false;d.rolled=true;monthly(d,p);if(p.shortfall>0){record(d,p,['Thiếu thanh khoản khi trả nghĩa vụ','Liquidity shortfall on obligations']);next(d,now);return true;}const die=1+hash(d.seed,p.month*17+seat*997)%6;p.position=(p.position+die)%w.cells;const tile=estateMap(d.world)[p.position];d.pending={die,tile:p.position};
  if(tile.kind==='market'){d.season=[.7,.85,1,1.15,1.3][hash(d.seed,p.month+seat*57)%5];record(d,p,['Mùa du lịch đổi hệ số doanh thu: '+d.season,'Tourism revenue factor changed: '+d.season]);}
  if(tile.kind==='surprise'){const event=hash(d.seed,p.month+seat*53)%3;if(event===0){const amount=10000*w.scale;pay(p,amount);record(d,p,['Chi phí sửa chữa bắt buộc: '+amount,'Mandatory repairs: '+amount]);}else d.pending.windfall=5000*w.scale;}
  const offer=estateOffer(d);if(offer?.action==='visit'&&offer.cost){const unpaid=pay(p,offer.cost);d.players[offer.owned.owner].cash+=offer.cost-unpaid;record(d,p,['Phí dịch vụ công trình: '+offer.cost,'Property service fee: '+offer.cost]);}
  return true;}
 if(!d.rolled||!d.pending)return false;
 if(action==='invest'){const o=estateOffer(d);if(!o||!['land','build','open'].includes(o.action)||!o.affordable)return false;p.cash-=o.cost;d.properties[p.position]={owner:seat,stage:(o.owned?.stage||0)+1};record(d,p,[[o.tile.name[0],['mua đất','góp vốn xây','hoàn công khai thác'][d.properties[p.position].stage-1]].join(' · '),[o.tile.name[1],['land purchased','construction funded','opened for business'][d.properties[p.position].stage-1]].join(' · ')]);}
 else if(action==='collect'){if(!d.pending.windfall)return false;p.cash+=d.pending.windfall;record(d,p,['Nhận hỗ trợ kinh doanh: '+d.pending.windfall,'Business support received: '+d.pending.windfall]);}
 else if(!['pass','timeout','continue'].includes(action))return false;
 if(action==='timeout')record(d,p,['Hết 60 giây: bỏ lựa chọn tự nguyện','60 seconds elapsed: optional choice declined']);next(d,now);return true;}
export function expireEstate(d,now=Date.now()){let count=0;while(d.active&&now>=d.deadline&&count<288){const deadline=d.deadline,seat=d.turn;if(!d.rolled)estateAct(d,seat,'roll',deadline);if(d.active&&d.turn===seat&&d.rolled)estateAct(d,seat,'timeout',deadline);count++;}return count;}
export function estateRanking(d){return d.players.map((p,i)=>({seat:i,name:p.name,worth:estateWorth(d,i),survived:!p.surrendered&&p.shortfall===0,month:p.month})).sort((a,b)=>Number(b.survived)-Number(a.survived)||b.worth-a.worth);}
